<span class="line"><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;">    &quot;interview:helper:ticket:&quot;</span><span style="--shiki-light:#383A42;--shiki-dark:#56B6C2;"> +</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> token,</span></span>
